import{_ as d,o as e,c as a,a0 as o}from"./chunks/framework.DQOulFGV.js";const g=JSON.parse('{"title":"聊天系统","description":"","frontmatter":{},"headers":[],"relativePath":"chat.md","filePath":"chat.md"}'),r={name:"chat.md"};function l(c,t,h,i,n,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="聊天系统" tabindex="-1">聊天系统 <a class="header-anchor" href="#聊天系统" aria-label="Permalink to &quot;聊天系统&quot;">​</a></h1><p>聊天系统支持普通聊天、全服喊话、私聊与消息美化。</p><h2 id="普通聊天" tabindex="-1">普通聊天 <a class="header-anchor" href="#普通聊天" aria-label="Permalink to &quot;普通聊天&quot;">​</a></h2><p>直接在聊天框输入内容即可发送，全服玩家都能看到。</p><h2 id="全服喊话" tabindex="-1">全服喊话 <a class="header-anchor" href="#全服喊话" aria-label="Permalink to &quot;全服喊话&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>!all &lt;内容&gt;</code></td><td>全服喊话</td></tr><tr><td><code>/global &lt;内容&gt;</code></td><td>全服喊话</td></tr><tr><td><code>/shout &lt;内容&gt;</code></td><td>全服喊话</td></tr></tbody></table><p>在消息前加 <code>!all</code>，或使用上述指令，即可让消息以全局频道广播出去。</p><h2 id="私聊" tabindex="-1">私聊 <a class="header-anchor" href="#私聊" aria-label="Permalink to &quot;私聊&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/msg &lt;玩家&gt; &lt;内容&gt;</code></td><td>私聊某玩家</td></tr><tr><td><code>/tell &lt;玩家&gt; &lt;内容&gt;</code></td><td>同上</td></tr><tr><td><code>/m &lt;玩家&gt; &lt;内容&gt;</code></td><td>同上</td></tr><tr><td><code>/w &lt;玩家&gt; &lt;内容&gt;</code></td><td>同上</td></tr></tbody></table><p>私聊消息只有你和对方能看到。</p><h2 id="消息美化" tabindex="-1">消息美化 <a class="header-anchor" href="#消息美化" aria-label="Permalink to &quot;消息美化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/trchat color &lt;颜色&gt;</code></td><td>设置你聊天的文字颜色</td></tr><tr><td><code>/trchat tellsimple &lt;玩家&gt; &lt;内容&gt;</code></td><td>以纯文本格式私聊</td></tr><tr><td><code>/trchat tellmini &lt;玩家&gt; &lt;内容&gt;</code></td><td>以支持富文本的格式私聊</td></tr></tbody></table><p>颜色可选如：<code>red</code>、<code>green</code>、<code>blue</code>、<code>gold</code>、<code>gray</code> 等。</p><h2 id="屏蔽与忽略" tabindex="-1">屏蔽与忽略 <a class="header-anchor" href="#屏蔽与忽略" aria-label="Permalink to &quot;屏蔽与忽略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/ignore &lt;玩家&gt;</code></td><td>忽略该玩家的聊天与私聊；再次执行可取消忽略</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>聊天有 <strong>2 秒冷却</strong>，请勿刷屏。</li><li>单条消息最长 <strong>100 个汉字/字符</strong>。</li><li>短时间内重复发送相同内容会被拦截。</li><li>请遵守服务器聊天规则：不刷屏、不广告、不辱骂、不引战。</li></ul>',17)])])}const u=d(r,[["render",l]]);export{g as __pageData,u as default};
